// optional chaining handles undefined
arr[i]?.toUpperCase();
record[key]?.trim();

// nullish coalescing provides a fallback
arr[i] ?? 'missing';

// explicit guard narrows both the index and the unknown value
if (arr[i] !== undefined) {
  arr[i].toUpperCase();
}

if (typeof value === 'string') {
  value.length;
